#include <iostream>
#include <string>
using namespace std;

class Cat {
protected:
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    virtual void speak() const {
        cout << name << "：喵～" << endl;
    }
};

class OrangeCat : public Cat {
public:
    OrangeCat(string n, int f) : Cat(n, f) {}
    void speak() const override {
        cout << name << "：本喵是橘猫，吃了 " << fish << " 条，喵喵喵！" << endl;
    }
};

class TabbyCat : public Cat {
public:
    TabbyCat(string n, int f) : Cat(n, f) {}
    void speak() const override {
        cout << name << "：本喵是狸花猫，吃了 " << fish << " 条，喵呜～" << endl;
    }
};

class BlackCat : public Cat {
public:
    BlackCat(string n, int f) : Cat(n, f) {}
    void speak() const override {
        cout << name << "：本喵是黑猫，吃了 " << fish << " 条，喵嗷～" << endl;
    }
};

int main() {
    int a = 0;
    int b = 0;
    int c = 0;
    cin >> a >> b >> c;

    OrangeCat o("{orangeName}", a);
    TabbyCat t("{tabbyName}", b);
    BlackCat k("{blackName}", c);

    Cat* cats[3];
    cats[0] = &o;
    cats[1] = &t;
    cats[2] = &k;

    for (int i = 0; i < 3; i++) {
        cats[i]->speak();
    }
    return 0;
}
